from pydantic import BaseModel, root_validator, ValidationError
from typing import Any

class RangeModel(BaseModel):
    lo: int
    hi: int

    @root_validator
    def validate_range(cls, values: dict) -> dict:
        lo = values.get('lo')
        hi = values.get('hi')
        if hi < lo:
            raise ValidationError([
                {
                    'loc': ('__root__',),
                    'msg': 'hi must be greater than or equal to lo',
                    'type': 'value_error'
                }
            ], cls)
        return values

def make_range(lo, hi):
    return RangeModel(lo=lo, hi=hi)
```

